/**
 * Icon asset registry — the single source of truth for colorful PNG icons.
 *
 * Generated by `scripts/build-icon-assets.cjs`. Every key here has a matching
 * `/icons/<pack>/<key>-256.png` file in `public/`. If you add an icon, re-run the
 * script rather than editing this by hand, so the two never drift.
 *
 * See docs/COLORFUL_ICON_MIGRATION_PLAN.md for the mapping rationale.
 */
export const ICON_REGISTRY = {
  'financial-statistics': 'accounting',
  'financial-graph-growth': 'accounting',
  'financial-report': 'accounting',
  'financial-analytics': 'accounting',
  'tax-calculator': 'accounting',
  contract: 'accounting',
  container: 'delivery',
  support: 'delivery',
  gps: 'delivery',
  'air-transport': 'delivery',
  'package-for-delivery': 'delivery',
  'delivery-list': 'delivery',
  'delivery-file': 'delivery',
  'open-box': 'delivery',
  'cargo-boat': 'delivery',
  shield: 'cyber',
  server: 'cyber',
  alert: 'cyber',
  telescope: 'it',
  'search-from-code': 'it',
  'add-to-basket': 'it',
  robot: 'it',
  articles: 'it',
  'laptop-settings': 'it',
} as const;

export type IconKey = keyof typeof ICON_REGISTRY;
export type IconPack = (typeof ICON_REGISTRY)[IconKey];

/** Default icon used when a lookup misses. */
export const FALLBACK_ICON: { name: IconKey; pack: IconPack } = {
  name: 'open-box',
  pack: 'delivery',
};
